raw_config:
system {
 host-name branch-srx-juniper-300;
 services {
  ssh {
   protocol-version v2;
  }
  web-management {
   https;
  }
 }
 login {
  idle-timeout 15;
 }
}
snmp {
 community enterprise_ro {
  authorization read-only;
 }
}

system {
 host-name core-agg-juniper-qfx;
 services {
  ssh {
   protocol-version v2;
   connection-limit 10;
   rate-limit 5;
  }
  web-management {
   https {
    port 443;
   }
  }
 }
 login {
  idle-timeout 10;
 }
 syslog {
  host 10.0.0.50 {
   any notice;
  }
 }
}
snmp {
 v3 {
  usm {
   local-engine {
    user admin-v3 {
     authentication-sha;
     privacy-aes128;
    }
   }
  }
 }
}

system {
 host-name edge-router-juniper;
 services {
  ssh {
   protocol-version v1;
  }
  telnet;
  web-management {
   http;
  }
 }
}
snmp {
 community public {
  authorization read-only;
 }
}

